import math

def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

n = 2400
primes = []
d = 2
while d * d <= n:
    while n % d == 0:
        primes.append(d)
        n //= d
    d += 1
if n > 1:
    primes.append(n)

print(f"Primes of {2400}: {primes}")
print(f"Count: {len(primes)}")
print(f"Product check: {math.prod(primes)}")
